/**
 * Helper function to render the platform icon based on key or URL
 */
export const getPlatformIcon = (keyOrUrl: string, className = 'w-5 h-5') => {
  const str = keyOrUrl.toLowerCase();
  if (str.includes('spotify')) return <SpotifyIcon className={className} />;
  if (str.includes('apple')) return <AppleMusicIcon className={className} />;
  if (str.includes('soundcloud')) return <SoundCloudIcon className={className} />;
  if (str.includes('audiomack')) return <AudiomackIcon className={className} />;
  if (str.includes('hearthis')) return <HearThisIcon className={className} />;
  if (str.includes('youtube')) return <YouTubeIcon className={className} />;
  return null;
};
